from dataclasses import dataclass, field


@dataclass
class CartItem:
    name: str
    price: float
    quantity: int


@dataclass
class Cart:
    _items: list = field(default_factory=list, repr=False)

    def add(self, name, price, quantity=1):
        for item in self._items:
            if item.name == name:
                item.quantity += quantity
                return
        self._items.append(CartItem(name=name, price=price, quantity=quantity))

    def item_count(self):
        return sum(item.quantity for item in self._items)

    def total(self):
        return round(sum(item.price * item.quantity for item in self._items), 2)

    def checkout(self, region="pk"):
        from ..payments.checkout import checkout
        from .orders import Order

        order = Order(items=[(item.price, item.quantity) for item in self._items])
        return checkout(order, region)
